import crypto from 'node:crypto';

// Encrypt an arbitrary document blob for storage using the recipient's RSA public key.
export function encryptDocument(documentBytes, recipientRsaPublicKeyPem) {
  // documentBytes can be several MB (a PDF, an image, an export, ...)
  return crypto.publicEncrypt(
    { key: recipientRsaPublicKeyPem, padding: crypto.constants.RSA_PKCS1_OAEP_PADDING },
    documentBytes // <-- the whole document, straight into RSA
  );
}
